/** Les délégations d'un gouvernorat, dans l'ordre des codes. */
export function delegationsDe(
  gouvernorat: GouvernoratCode,
): readonly Delegation[] {
  return DELEGATIONS.filter((d) => d.gouvernorat === gouvernorat);
}
